import java.util.*;

public class Cutting {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        String[] parts = line.split(" ");
        int n = Integer.parseInt(parts[0]);
        int coinsLeft = Integer.parseInt(parts[1]);
        String[] vals = scanner.nextLine().split(" ");
        int oddCount = 0, evenCount = 0, cutsCount = 0;
        List<Integer> diffList = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int currentVal = Integer.parseInt(vals[i]);
            if (currentVal % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (oddCount == evenCount) {
                int nextVal = Integer.parseInt(vals[i + 1]);
                int diff = Math.abs(nextVal - currentVal);
                diffList.add(diff);
            }
        }
        Collections.sort(diffList);
        for (int d : diffList) {
            if (d <= coinsLeft) {
                coinsLeft -= d;
                cutsCount++;
            } else {
                break;
            }
        }
        System.out.println(cutsCount);
    }
}
