#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

int main() {
    int n, coinsLeft;
    std::cin >> n >> coinsLeft;
    std::vector<int> vals(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> vals[i];
    }

    int oddCount = 0, evenCount = 0, cutsCount = 0;
    std::vector<int> diffList;

    for (int i = 0; i < n - 1; ++i) {
        int currentVal = vals[i];
        if (currentVal % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
        if (oddCount == evenCount) {
            int nextVal = vals[i + 1];
            int diff = std::abs(nextVal - currentVal);
            diffList.push_back(diff);
        }
    }

    std::sort(diffList.begin(), diffList.end());

    for (int d : diffList) {
        if (d <= coinsLeft) {
            coinsLeft -= d;
            ++cutsCount;
        } else {
            break;
        }
    }

    std::cout << cutsCount << std::endl;
    return 0;
}
